const topicTexts = {
1: `قَالَ النَّبِيُّ ﷺ : «مَنْ سَلَكَ طَرِيقاً يَلْتَمِسُ فِيهِ عِلْماً ؛ سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقاً إِلَى الجَنَّةِ»<br><br>
قَالَ النَّبِيُّ ﷺ : «مَنْ يُرِدِ اللَّهُ خَيْراً ؛ يُفَقِّهْهُ فِي الدِّينِ»<br><br>
قَالَ النَّبِيُّ ﷺ : «إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ : إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ»`,
2: `قَالَ النَّبِيُّ ﷺ : «خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ»<br><br>
قَالَ النَّبِيُّ ﷺ : «مَثَلُ الَّذِي يَقْرَأُ القُرْآنَ وَهُوَ حَافِظٌ لَهُ مَعَ السَّفَرَةِ الكِرَامِ البَرَرَةِ، وَمَثَلُ الَّذِي يَقْرَأُ وَهُوَ يَتَعَاهَدُهُ وَهُوَ عَلَيْهِ شَدِيدٌ ؛ فَلَهُ أَجْرَانِ»<br><br>
قَالَ النَّبِيُّ ﷺ : «اقْرَؤُوا القُرْآنَ؛ فَإِنَّهُ يَأْتِي يَوْمَ القِيَامَةِ شَفِيعاً لِأَصْحَابِهِ»`,
3: `قَالَ النَّبِيُّ ﷺ : «مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ، مَثَلُ الحَيِّ وَالمَيِّتِ»<br><br>
قَالَ النَّبِيُّ ﷺ : يَقُولُ اللَّهُ تَعَالَى : «أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَا ذَكَرْتُهُ فِي مَلَا خَيْرٍ مِنْهُمْ»<br><br>
قَالَ النَّبِيُّ ﷺ : «سَبَقَ المُفَرِّدُونَ»، قَالُوا : وَمَا المُفَرِّدُونَ يَا رَسُولَ اللَّهِ؟ قَالَ : «الذَّاكِرُونَ اللَّهَ كَثِيراً ، وَالذَّاكِرَاتُ»`,
4: `قَالَ النَّبِيُّ ﷺ : «وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ ، يَتْلُونَ كِتَابَ اللَّهِ، وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ ، وَغَشِيَتْهُمُ الرَّحْمَةُ ، وَحَفَّتْهُمُ المَلَائِكَةُ ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ»`,

5: `كَانَ النَّبِيُّ ﷺ إِذَا دَخَلَ الخَلَاءَ (١) قَالَ: «اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الخُبُثِ وَالخَبَائِثِ (٢)» (٣).`,
6: `كَانَ النَّبِيُّ ﷺ إِذَا خَرَجَ مِنَ الْغَائِطِ (١) قَالَ: «غُفْرَانَكَ (٢)» (٣).`,
7: `قَالَ النَّبِيُّ ﷺ: «مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ، فَيُبْلِغُ - أَوْ: فَيُسْبِغُ - الوُضُوءَ (١)، ثُمَّ يَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّداً عَبْدُ اللَّهِ وَرَسُولُهُ؛ إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الجَنَّةِ الثَّمَانِيَةُ، يَدْخُلُ مِنْ أَيِّهَا شَاءَ» (٢).`,
8: `١ - قَالَ النَّبِيُّ ﷺ: «إِذَا سَمِعْتُمُ المُؤَذِّنَ؛ فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ» (١).<br><br>٢ - قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ حِينَ يَسْمَعُ المُؤَذِّنَ (٢): أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبّاً، وَبِمُحَمَّدٍ رَسُولاً، وَبِالإِسْلَامِ دِيناً؛ غُفِرَ لَهُ ذَنْبُهُ» (٣).<br><br>٣ - قَالَ النَّبِيُّ ﷺ: «ثُمَّ قَالَ: حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ (١). ثُمَّ قَالَ: حَيَّ عَلَى الفَلَاحِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ» (٢).<br><br>٤ - قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ (٣)، وَالصَّلَاةِ القَائِمَةِ، آتِ مُحَمَّداً الوَسِيلَةَ وَالفَضِيلَةَ (٤)، وَابْعَثْهُ مَقَاماً مَحْمُوداً (٥) الَّذِي وَعَدْتَهُ؛ حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ القِيَامَةِ» (١) (٢).`,
9: `قَالَ النَّبِيُّ ﷺ: «إِذَا دَخَلَ أَحَدُكُمُ المَسْجِدَ فَلْيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ. وَإِذَا خَرَجَ فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ» (١).`,
10: `١ - كَانَ عُمَرُ بْنُ الخَطَّابِ ؓ إِذَا اسْتَفْتَحَ الصَّلَاةَ قَالَ: «سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ (١)، وَتَبَارَكَ اسْمُكَ (٢)، وَتَعَالَى جَدُّكَ (٣)، وَلَا إِلَهَ غَيْرُكَ» (٤).<br><br>٢ - قَالَ أَبُو هُرَيْرَةَ ؓ: «كَانَ النَّبِيُّ ﷺ إِذَا كَبَّرَ فِي الصَّلَاةِ، سَكَتَ هُنَيَّةً (٥) قَبْلَ أَنْ يَقْرَأَ. فَقُلْتُ: يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي، أَرَأَيْتَ سُكُوتَكَ بَيْنَ التَّكْبِيرِ وَالقِرَاءَةِ، مَا تَقُولُ؟ قَالَ: أَقُولُ: اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبِ. اللَّهُمَّ نَقِّنِي (١) مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ (٢). اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالمَاءِ وَالبَرَدِ (٣)» (٤).<br><br>٣ - كَانَ النَّبِيُّ ﷺ إِذَا قَامَ إِلَى الصَّلَاةِ قَالَ: «وَجَّهْتُ وَجْهِيَ (١) لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ (٢) حَنِيفاً (٣)، وَمَا أَنَا مِنَ المُشْرِكِينَ. إِنَّ صَلَاتِي وَنُسُكِي (٤) وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ العَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ، وَأَنَا مِنَ المُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لَا إِلَهَ إِلَّا أَنْتَ. أَنْتَ رَبِّي، وَأَنَا عَبْدُكَ. ظَلَمْتُ نَفْسِي، وَاعْتَرَفْتُ بِذَنْبِي، فَاغْفِرْ لِي ذُنُوبِي جَمِيعاً؛ إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلَاقِ؛ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ. وَاصْرِفْ عَنِّي سَيِّئَهَا؛ لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ. لَبَّيْكَ وَسَعْدَيْكَ (١)، وَالخَيْرُ كُلُّهُ فِي يَدَيْكَ، وَالشَّرُّ لَيْسَ إِلَيْكَ. أَنَا بِكَ وَإِلَيْكَ (٢)، تَبَارَكْتَ (٣) وَتَعَالَيْتَ (٤). أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ» (١).<br><br>٤ - كَانَ رَسُولُ اللَّهِ ﷺ إِذَا قَامَ مِنَ اللَّيْلِ يَتَهَجَّدُ قَالَ: «اللَّهُمَّ لَكَ الحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الحَمْدُ أَنْتَ رَبُّ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، أَنْتَ الحَقُّ، وَوَعْدُكَ الحَقُّ، وَقَوْلُكَ الحَقُّ، وَلِقَاؤُكَ الحَقُّ، وَالجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ ﷺ حَقٌّ، وَالسَّاعَةُ حَقٌّ. اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ إِلَهِي لَا إِلَهَ إِلَّا أَنْتَ» (١).<br><br>٥ - كَانَ رَسُولُ اللَّهِ ﷺ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ: «اللَّهُمَّ رَبَّ جَبْرَائِيلَ، وَمِيكَائِيلَ، وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالأَرْضِ، عَالِمَ الغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الحَقِّ بِإِذْنِكَ؛ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ» (٢).`,
11: `أَتَى عُثْمَانُ بْنُ أَبِي العَاصِ ؓ إِلَى النَّبِيِّ ﷺ، فَقَالَ: «يَا رَسُولَ اللَّهِ، إِنَّ الشَّيْطَانَ قَدْ حَالَ بَيْنِي وَبَيْنَ صَلَاتِي وَقِرَاءَتِي يَلْبِسُهَا عَلَيَّ (١). فَقَالَ النَّبِيُّ ﷺ: ذَاكَ شَيْطَانٌ يُقَالُ لَهُ: خِنْزَبٌ. فَإِذَا أَحْسَسْتَهُ؛ فَتَعَوَّذُ بِاللَّهِ مِنْهُ، وَاتْفُلْ (٢) عَلَى يَسَارِكَ - ثَلَاثاً -. قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَهُ اللَّهُ عَنِّي» (١).`,
12: `١ - كَانَ النَّبِيُّ ﷺ يَقُولُ فِي رُكُوعِهِ: «سُبْحَانَ رَبِّيَ العَظِيمِ» (١).<br><br>٢ - كَانَ النَّبِيُّ ﷺ إِذَا رَكَعَ قَالَ: «اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ. خَشَعَ لَكَ سَمْعِي، وَبَصَرِي، وَمُخِّي، وَعَظْمِي، وَعَصَبِي» (٢).<br><br>٣ - كَانَ النَّبِيُّ ﷺ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ: «سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي» (١).<br><br>٤ - كَانَ النَّبِيُّ ﷺ يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ: «سُبُّوحٌ قُدُّوسٌ (٢)، رَبُّ المَلَائِكَةِ وَالرُّوحِ (٣)» (٤).<br><br>٥ - كَانَ النَّبِيُّ ﷺ يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ: «سُبْحَانَ ذِي الجَبَرُوتِ (٥) وَالمَلَكُوتِ (٦) وَالكِبْرِيَاءِ وَالعَظَمَةِ» (٧).`,
13: `١ - رَفَعَ النَّبِيُّ ﷺ رَأْسَهُ مِنَ الرَّكْعَةِ وَقَالَ: «سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ». فَقَالَ رَجُلٌ وَرَاءَهُ: «رَبَّنَا وَلَكَ الحَمْدُ، حَمْداً كَثِيراً، طَيِّباً، مُبَارَكاً فِيهِ». فَلَمَّا انْصَرَفَ قَالَ: «مَنِ المُتَكَلِّمُ؟» قَالَ: أَنَا. قَالَ: «رَأَيْتُ بِضْعَةً وَثَلَاثِينَ مَلَكاً يَبْتَدِرُونَهَا (١) أَيُّهُمْ يَكْتُبُهَا أَوَّلُ» (٢).<br><br>٢ - كَانَ النَّبِيُّ ﷺ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: «رَبَّنَا لَكَ الحَمْدُ، مِلْءَ السَّمَوَاتِ وَالأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ. أَهْلَ الثَّنَاءِ (١) وَالمَجْدِ (٢). أَحَقُّ مَا قَالَ العَبْدُ (٣)، وَكُلُّنَا لَكَ عَبْدٌ. اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ» (٤) (٥).`,
14: `١ - كَانَ النَّبِيُّ ﷺ يَقُولُ فِي سُجُودِهِ: «سُبْحَانَ رَبِّيَ الأَعْلَى» (١).<br><br>٢ - كَانَ النَّبِيُّ ﷺ يَقُولُ فِي سُجُودِهِ: «اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ؛ دِقَّهُ وَجِلَّهُ (٢)، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ» (٣).<br><br>٣ - كَانَ النَّبِيُّ ﷺ إِذَا سَجَدَ قَالَ: «اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ. سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ، وَشَقَّ (١) سَمْعَهُ وَبَصَرَهُ. تَبَارَكَ اللَّهُ أَحْسَنُ الخَالِقِينَ» (٢).`,
15: `١ - قَالَ النَّبِيُّ ﷺ: «قُولُوا: التَّحِيَّاتُ لِلَّهِ (١)، وَالصَّلَوَاتُ (٢)، وَالطَّيِّبَاتُ (٣). السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ» (٤).<br><br>٢ - قَالَ النَّبِيُّ ﷺ: «قُولُوا: اللَّهُمَّ صَلِّ (١) عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ؛ إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ (٢) عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ؛ إِنَّكَ حَمِيدٌ مَجِيدٌ» (٣).`,
16: `١ - قَالَ النَّبِيُّ ﷺ: «إِذَا تَشَهَّدَ أَحَدُكُمْ؛ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ، يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ القَبْرِ، وَمِنْ فِتْنَةِ المَحْيَا وَالمَمَاتِ (١)، وَمِنْ شَرِّ فِتْنَةِ المَسِيحِ الدَّجَّالِ» (٢).<br><br>٢ - كَانَ النَّبِيُّ ﷺ يَتَعَوَّذُ دُبُرَ الصَّلَاةِ: «اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الجُبْنِ (٣)، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ العُمُرِ (١)، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ» (٢).<br><br>٣ - كَانَ النَّبِيُّ ﷺ يَقُولُ بَيْنَ التَّشَهُدِ وَالتَّسْلِيمِ: «اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ المُقَدِّمُ وَأَنْتَ المُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ» (٣).`,
17: `١ - كَانَ النَّبِيُّ ﷺ إِذَا انْصَرَفَ مِنْ صَلَاتِهِ: اسْتَغْفَرَ - ثَلَاثاً -، وَقَالَ: «اللَّهُمَّ أَنْتَ السَّلَامُ (١)، وَمِنْكَ السَّلَامُ (٢)، تَبَارَكْتَ يَا ذَا الجَلَالِ (٣) وَالإِكْرَامِ» (٤).<br><br>٢ - كَانَ النَّبِيُّ ﷺ إِذَا فَرَغَ مِنَ الصَّلَاةِ وَسَلَّمَ، قَالَ: «لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ» (١).<br><br>٣ - كَانَ النَّبِيُّ ﷺ يَقُولُ فِي دُبُرِ (٢) كُلِّ صَلَاةٍ حِينَ يُسَلِّمُ: «لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ. لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ. لَهُ النِّعْمَةُ، وَلَهُ الفَضْلُ، وَلَهُ الثَّنَاءُ الحَسَنُ. لَا إِلَهَ إِلَّا اللَّهُ، مُخْلِصِينَ لَهُ الدِّينَ، وَلَوْ كَرِهَ الكَافِرُونَ» (١).<br><br>٤ - قَالَ النَّبِيُّ ﷺ: «يَا مُعَاذُ، لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُولُ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ» (٢).<br><br>٥ - قَالَ النَّبِيُّ ﷺ: «مَنْ سَبَّحَ اللَّهَ فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثاً وَثَلَاثِينَ، وَحَمِدَ اللَّهَ ثَلَاثاً وَثَلَاثِينَ، وَكَبَّرَ اللَّهَ ثَلَاثاً وَثَلَاثِينَ؛ فَتِلْكَ تِسْعَةٌ وَتِسْعُونَ، وَقَالَ تَمَامَ المِئَةِ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ؛ غُفِرَتْ خَطَايَاهُ؛ وَإِنْ كَانَتْ مِثْلَ زَبَدِ البَحْرِ (١)» (٢).<br><br>٦ - قَالَ النَّبِيُّ ﷺ: «مَنْ قَرَأَ آيَةَ الكُرْسِيِّ فِي دُبُرِ كُلِّ صَلَاةٍ مَكْتُوبَةٍ؛ لَمْ يَمْنَعْهُ مِنْ دُخُولِ الجَنَّةِ إِلَّا أَنْ يَمُوتَ» (٣).<br><br>٧ - عَنْ عُقْبَةَ بْنِ عَامِرٍ ؓ قَالَ: «أَمَرَنِي رَسُولُ اللَّهِ ﷺ أَنْ أَقْرَأَ بِالمُعَوِّذَاتِ (١) دُبُرَ كُلِّ صَلَاةٍ» (٢).`,
18: `قَالَ الحَسَنُ بْنُ عَلِيٍّ ؓ: عَلَّمَنِي النَّبِيُّ ﷺ كَلِمَاتٍ أَقُولُهُنَّ فِي الوِتْرِ: «اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي (١) فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ» (٢).`,
19: `كَانَ النَّبِيُّ ﷺ إِذَا سَلَّمَ مِنَ الوِتْرِ قَالَ: «سُبْحَانَ المَلِكِ القُدُّوسِ» - ثَلَاثاً - وَيَرْفَعُ صَوْتَهُ بِالثَّالِثَةِ (١).`,
20: `عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ ؓ قَالَ: «كَانَ النَّبِيُّ ﷺ يُعَلِّمُنَا الاسْتِخَارَةَ (١) فِي الأُمُورِ كُلِّهَا، كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ القُرْآنِ. يَقُولُ: إِذَا هَمَّ أَحَدُكُمْ بِالأَمْرِ (٢)، فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الفَرِيضَةِ، ثُمَّ لْيَقُلِ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ (٣)، وَأَسْأَلُكَ مِنْ فَضْلِكَ العَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلاَّمُ الغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي - أَوْ قَالَ: عَاجِلِ أَمْرِي وَآجِلِهِ -؛ فَاقْدُرْهُ لِي، وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ. وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي - أَوْ قَالَ: فِي عَاجِلِ أَمْرِي وَآجِلِهِ -؛ فَاصْرِفْهُ عَنِّي، وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ. قَالَ: وَيُسَمِّي حَاجَتَهُ» (١) (٢).`,
21: `كَانَ النَّبِيُّ ﷺ إِذَا اشْتَكَى يَقْرَأُ عَلَى نَفْسِهِ بِالمُعَوِّذَاتِ وَيَنْفُثُ.<br><br>
عَنْ عُثْمَانَ بْنِ أَبِي العَاصِ رضي الله عنه: أَنَّهُ شَكَا إِلَى النَّبِيِّ ﷺ وَجَعًا يَجِدُهُ فِي جَسَدِهِ مُنْذُ أَسْلَمَ، فَقَالَ لَهُ النَّبِيُّ ﷺ: «ضَعْ يَدَكَ عَلَى الَّذِي تَأَلَّمَ مِنْ جَسَدِكَ، وَقُلْ: بِسْمِ اللهِ -ثَلَاثًا-، وَقُلْ -سَبْعَ مَرَّاتٍ-: أَعُوذُ بِاللهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ».`,
22: `كَانَ النَّبِيُّ ﷺ إِذَا دَخَلَ عَلَى مَرِيضٍ يَعُودُهُ قَالَ لَهُ: «لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللَّهُ».<br><br>
كَانَ النَّبِيُّ ﷺ يُعَوِّذُ بَعْضَ أَهْلِهِ، يَمْسَحُ بِيَدِهِ اليُمْنَى وَيَقُولُ: «اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ البَأْسَ، اشْفِهِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا».<br><br>
أَتَى جِبْرِيلُ النَّبِيَّ ﷺ فَقَالَ: يَا مُحَمَّدُ اشْتَكَيْتَ؟ فَقَالَ: «نَعَمْ»، قَالَ: «بِسْمِ اللهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللهُ يَشْفِيكَ، بِسْمِ اللهِ أَرْقِيكَ».<br><br>
قَالَ النَّبِيُّ ﷺ: «مَنْ عَادَ مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ، فَقَالَ عِنْدَهُ -سَبْعَ مِرَارٍ-: أَسْأَلُ اللَّهَ العَظِيمَ رَبَّ العَرْشِ العَظِيمِ أَنْ يَشْفِيَكَ؛ إِلَّا عَافَاهُ اللَّهُ مِنْ ذَلِكَ المَرَضِ».`,
23: `قَالَ النَّبِيُّ ﷺ: «مَنْ كَانَ آخِرُ كَلَامِهِ: لَا إِلَهَ إِلَّا اللَّهُ؛ دَخَلَ الجَنَّةَ».`,
24: `قَالَ عَوْفُ بْنُ مَالِكٍ رضي الله عنه: صَلَّى النَّبِيُّ ﷺ عَلَى جَنَازَةٍ، فَحَفِظْتُ مِنْ دُعَائِهِ وَهُوَ يَقُولُ: «اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ. وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالمَاءِ وَالثَّلْجِ وَالبَرَدِ. وَنَقِّهِ مِنَ الخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ. وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ. وَأَدْخِلْهُ الجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ القَبْرِ، وَمِنْ عَذَابِ النَّارِ».`,
25: `عَنْ أُسَامَةَ بْنِ زَيْدٍ رضي الله عنهما قَالَ: كُنَّا عِنْدَ النَّبِيِّ ﷺ، فَأَرْسَلَتْ إِلَيْهِ إِحْدَى بَنَاتِهِ تَدْعُوهُ، وَتُخْبِرُهُ أَنَّ صَبِيًّا لَهَا -أَوِ ابْنًا لَهَا- فِي المَوْتِ، فَقَالَ لِلرَّسُولِ: «ارْجِعْ إِلَيْهَا، فَأَخْبِرْهَا أَنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى؛ فَمُرْهَا فَلْتَصْبِرْ وَلْتَحْتَسِبْ».`,
26: `كَانَ النَّبِيُّ ﷺ إِذَا فَرَغَ مِنْ دَفْنِ المَيِّتِ وَقَفَ عَلَيْهِ، فَقَالَ: «اسْتَغْفِرُوا لِأَخِيكُمْ، وَسَلُوا اللَّهَ لَهُ بِالتَّثْبِيتِ؛ فَإِنَّهُ الآنَ يُسْأَلُ».`,
27: `عَنْ بُرَيْدَةَ رضي الله عنه قَالَ: كَانَ النَّبِيُّ ﷺ يُعَلِّمُهُمْ إِذَا خَرَجُوا إِلَى المَقَابِرِ: «السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ المُؤْمِنِينَ وَالمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ العَافِيَةَ».`,
28: `كَانَ النَّبِيُّ ﷺ يَقُولُ عِنْدَ الكَرْبِ: «لَا إِلَهَ إِلَّا اللهُ العَظِيمُ الحَلِيمُ. لَا إِلَهَ إِلَّا اللهُ رَبُّ العَرْشِ العَظِيمِ. لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ، وَرَبُّ الأَرْضِ، وَرَبُّ العَرْشِ الكَرِيمِ».`,
29: `قَالَ النَّبِيُّ ﷺ: «وَإِنْ أَصَابَكَ شَيْءٌ، فَلَا تَقُلْ: لَوْ أَنِّي فَعَلْتُ؛ كَانَ كَذَا وَكَذَا، وَلَكِنْ قُلْ: قَدَّرَ اللهُ وَمَا شَاءَ فَعَلَ؛ فَإِنَّ (لَوْ) تَفْتَحُ عَمَلَ الشَّيْطَانِ».<br><br>
قَالَ النَّبِيُّ ﷺ: «مَا مِنْ عَبْدٍ تُصِيبُهُ مُصِيبَةٌ، فَيَقُولُ: ﴿إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ﴾، اللَّهُمَّ اؤْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا؛ إِلَّا أَجَرَهُ اللهُ فِي مُصِيبَتِهِ، وَأَخْلَفَ لَهُ خَيْرًا مِنْهَا».`,
30: `كَانَ النَّبِيُّ ﷺ إِذَا خَافَ قَوْمًا قَالَ: «اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ».`,
31: `دَعَا النَّبِيُّ ﷺ عَلَى الأَحْزَابِ فَقَالَ: «اللَّهُمَّ مُنْزِلَ الكِتَابِ، سَرِيعَ الحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ».`,
32: `كَانَ النَّبِيُّ ﷺ إِذَا وَدَّعَ أَحَدًا قَالَ: «أَسْتَوْدِعُ اللهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ».`,
33: `كَانَ النَّبِيُّ ﷺ إِذَا اسْتَوَى عَلَى بَعِيرِهِ خَارِجًا إِلَى سَفَرٍ: كَبَّرَ -ثَلَاثًا-، ثُمَّ قَالَ: «﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ﴾، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ العَمَلِ مَا تَرْضَى. اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ. اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالخَلِيفَةُ فِي الأَهْلِ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ المَنْظَرِ، وَسُوءِ المُنْقَلَبِ فِي المَالِ وَالأَهْلِ». وَإِذَا رَجَعَ قَالَهُنَّ، وَزَادَ فِيهِنَّ: «آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ».`,
34: `قَالَ جَابِرُ بْنُ عَبْدِ اللهِ رضي الله عنهما: كُنَّا إِذَا صَعِدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا.`,
35: `كَانَ النَّبِيُّ ﷺ إِذَا كَانَ فِي سَفَرٍ وَأَسْحَرَ يَقُولُ: «سَمِعَ سَامِعٌ بِحَمْدِ اللهِ وَحُسْنِ بَلَائِهِ عَلَيْنَا، رَبَّنَا صَاحِبْنَا، وَأَفْضِلْ عَلَيْنَا، عَائِذًا بِاللهِ مِنَ النَّارِ».`,
36: `لَمْ يَرَ النَّبِيُّ ﷺ قَرْيَةً يُرِيدُ دُخُولَهَا؛ إِلَّا قَالَ حِينَ يَرَاهَا: «اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الأَرَضِينَ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضْلَلْنَ، وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ، فَإِنَّا نَسْأَلُكَ خَيْرَ هَذِهِ القَرْيَةِ وَخَيْرَ أَهْلِهَا، وَنَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا وَشَرِّ مَا فِيهَا».`,
37: `كَانَ النَّبِيُّ ﷺ إِذَا قَفَلَ مِنْ غَزْوٍ، أَوْ حَجٍّ، أَوْ عُمْرَةٍ: يُكَبِّرُ عَلَى كُلِّ شَرَفٍ مِنَ الأَرْضِ -ثَلَاثَ تَكْبِيرَاتٍ-، ثُمَّ يَقُولُ: «لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. آيِبُونَ، تَائِبُونَ، عَابِدُونَ، سَاجِدُونَ، لِرَبِّنَا حَامِدُونَ. صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ».`,
38: `كَانَتْ تَلْبِيَةُ النَّبِيِّ ﷺ: «لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الحَمْدَ وَالنِّعْمَةَ لَكَ وَالمُلْكَ، لَا شَرِيكَ لَكَ».`,
39: `طَافَ النَّبِيُّ ﷺ بِالبَيْتِ وَهُوَ عَلَى بَعِيرٍ؛ كُلَّمَا أَتَى عَلَى الرُّكْنِ أَشَارَ إِلَيْهِ بِشَيْءٍ فِي يَدِهِ، وَكَبَّرَ.`,
40: `كَانَ النَّبِيُّ ﷺ يَقُولُ بَيْنَ الرُّكْنَيْنِ: «﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾».`,
41: `كَانَ النَّبِيُّ ﷺ إِذَا صَعِدَ عَلَى الصَّفَا وَالمَرْوَةِ: اسْتَقْبَلَ القِبْلَةَ، فَوَحَّدَ اللهَ وَكَبَّرَهُ، وَقَالَ: «لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ»، ثُمَّ دَعَا بَيْنَ ذَلِكَ. قَالَ مِثْلَ هَذَا -ثَلَاثَ مَرَّاتٍ-.`,
42: `أَتَى النَّبِيُّ ﷺ المَشْعَرَ الحَرَامَ، فَاسْتَقْبَلَ القِبْلَةَ، فَدَعَا اللهَ، وَكَبَّرَهُ، وَهَلَّلَهُ، وَوَحَّدَهُ، فَلَمْ يَزَلْ وَاقِفًا حَتَّى أَسْفَرَ جِدًّا، فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ.`,
43: `كَانَ النَّبِيُّ ﷺ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ.`,
44: `ضَحَّى النَّبِيُّ ﷺ بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ، ذَبَحَهُمَا بِيَدِهِ، وَسَمَّى وَكَبَّرَ.`,
45: `قَالَ النَّبِيُّ ﷺ: «إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ، فَذَكَرَ اللَّهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ، قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ، وَلَا عَشَاءَ».`,
46: `كَانَ النَّبِيُّ ﷺ إِذَا اسْتَجَدَّ ثَوْبًا سَمَّاهُ بِاسْمِهِ -عِمَامَةً، أَوْ قَمِيصًا، أَوْ رِدَاءً-، ثُمَّ يَقُولُ: «اللَّهُمَّ لَكَ الحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ». `,
47: `كَانَ النَّاسُ إِذَا رَأَوْا أَوَّلَ الثَّمَرِ جَاؤُوا بِهِ إِلَى النَّبِيِّ ﷺ، فَإِذَا أَخَذَهُ رَسُولُ اللَّهِ ﷺ قَالَ: «اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا». `,
48: `قَالَ النَّبِيُّ ﷺ: «إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلْيَقُلْ: بِسْمِ اللَّهِ. فَإِنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ: بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ». `,
49: `كَانَ النَّبِيُّ ﷺ إِذَا رَفَعَ مَائِدَتَهُ قَالَ: «الحَمْدُ لِلَّهِ كَثِيرًا، طَيِّبًا، مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ، وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا». `,
50: `أَكَلَ النَّبِيُّ ﷺ عِنْدَ رَجُلٍ وَشَرِبَ، فَلَمَّا فَرَغَ قَالَ: «اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ، وَارْحَمْهُمْ». `,
51: `كَانَ النَّبِيُّ ﷺ إِذَا رَفَّأَ الإِنْسَانَ إِذَا تَزَوَّجَ قَالَ: «بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي الخَيْرِ». `,
52: `قَالَ النَّبِيُّ ﷺ: «لَوْ أَنَّ أَحَدَكُمْ إِذَا أَرَادَ أَنْ يَأْتِيَ أَهْلَهُ قَالَ: بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا؛ فَإِنَّهُ إِنْ يُقَدَّرْ بَيْنَهُمَا وَلَدٌ فِي ذَلِكَ، لَمْ يَضُرَّهُ شَيْطَانٌ أَبَدًا». `,
53: `قَالَ النَّبِيُّ ﷺ: «إِذَا كَانَ جُنْحُ اللَّيْلِ -أَوْ: أَمْسَيْتُمْ-؛ فَكُفُّوا صِبْيَانَكُمْ، فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَتْ سَاعَةٌ مِنَ اللَّيْلِ فَخَلُّوهُمْ. وَأَغْلِقُوا الأَبْوَابَ، وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا مُغْلَقًا. وَأَوْكُوا قِرَبَكُمْ، وَاذْكُرُوا اسْمَ اللَّهِ. وَخَمِّرُوا آنِيَتَكُمْ، وَاذْكُرُوا اسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرِضُوا عَلَيْهَا شَيْئًا. وَأَطْفِئُوا مَصَابِيحَكُمْ».<br><br>قَالَ النَّبِيُّ ﷺ: «الآيَتَانِ مِنْ آخِرِ سُورَةِ البَقَرَةِ، مَنْ قَرَأَهُمَا فِي لَيْلَةٍ كَفَتَاهُ». `,
54: `قَالَ النَّبِيُّ ﷺ: «إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ، فَلْيَأْخُذْ دَاخِلَةَ إِزَارِهِ؛ فَلْيَنْفُضْ بِهَا فِرَاشَهُ، وَلْيُسَمِّ اللَّهَ، فَإِنَّهُ لَا يَعْلَمُ مَا خَلَفَهُ بَعْدَهُ عَلَى فِرَاشِهِ. فَإِذَا أَرَادَ أَنْ يَضْطَجِعَ؛ فَلْيَضْطَجِعْ عَلَى شِقِّهِ الْأَيْمَنِ، وَلْيَقُلْ: سُبْحَانَكَ اللَّهُمَّ رَبِّي، بِكَ وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَاغْفِرْ لَهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا أَوَيْتَ إِلَى فِرَاشِكَ، فَاقْرَأْ آيَةَ الْكُرْسِيِّ: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾؛ فَإِنَّهُ لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ، وَلَا يَقْرَبُكَ شَيْطَانٌ حَتَّى تُصْبِحَ».<br><br>كَانَ النَّبِيُّ ﷺ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ: جَمَعَ كَفَّيْهِ، ثُمَّ نَفَثَ فِيهِمَا، فَقَرَأَ فِيهِمَا: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾، وَ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾، وَ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾، ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ، يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ.<br><br>كَانَ النَّبِيُّ ﷺ إِذَا أَرَادَ أَنْ يَنَامَ قَالَ: «بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا».<br><br>قَالَ النَّبِيُّ ﷺ: «اللَّهُمَّ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ».<br><br>كَانَ النَّبِيُّ ﷺ إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ: «الحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ».<br><br>قَالَ النَّبِيُّ ﷺ لِعَلِيٍّ وَفَاطِمَةَ رضي الله عنهما: «أَلَا أَدُلُّكُمَا عَلَى مَا هُوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ؟ إِذَا أَوَيْتُمَا إِلَى فِرَاشِكُمَا، أَوْ أَخَذْتُمَا مَضَاجِعَكُمَا، فَسَبِّحَا ثَلَاثًا وَثَلَاثِينَ، وَاحْمَدَا ثَلَاثًا وَثَلَاثِينَ، وَكَبِّرَا أَرْبَعًا وَثَلَاثِينَ؛ فَهُوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ».<br><br>قَالَ أَبُو هُرَيْرَةَ رضي الله عنه: كَانَ النَّبِيُّ ﷺ يَأْمُرُنَا إِذَا أَرَادَ أَحَدُنَا أَنْ يَنَامَ: أَنْ يَضْطَجِعَ عَلَى شِقِّهِ الْأَيْمَنِ، ثُمَّ يَقُولَ: «اللَّهُمَّ رَبَّ السَّمَاوَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ، وَأَغْنِنَا مِنَ الْفَقْرِ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا أَخَذْتَ مَضْجَعَكَ: فَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ، ثُمَّ اضْطَجِعْ عَلَى شِقِّكَ الْأَيْمَنِ، ثُمَّ قُلْ: اللَّهُمَّ إِنِّي أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ».<br><br>«وَاجْعَلْهُنَّ مِنْ آخِرِ كَلَامِكَ، فَإِنْ مِتَّ مِنْ لَيْلَتِكَ، مِتَّ وَأَنْتَ عَلَى الْفِطْرَةِ». `,
55: `قَالَ النَّبِيُّ ﷺ: «مَنْ تَعَارَّ مِنَ اللَّيْلِ، فَقَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. الْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ. ثُمَّ قَالَ: اللَّهُمَّ اغْفِرْ لِي، أَوْ دَعَا؛ اسْتُجِيبَ لَهُ. فَإِنْ تَوَضَّأَ وَصَلَّى؛ قُبِلَتْ صَلَاتُهُ».<br><br>كَانَ النَّبِيُّ ﷺ إِذَا اسْتَيْقَظَ قَالَ: «الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ».<br><br>قَالَ النَّبِيُّ ﷺ: «يَعْقِدُ الشَّيْطَانُ عَلَى قَافِيَةِ رَأْسِ أَحَدِكُمْ إِذَا هُوَ نَامَ ثَلَاثَ عُقَدٍ، يَضْرِبُ كُلَّ عُقْدَةٍ مَكَانَهَا: عَلَيْكَ لَيْلٌ طَوِيلٌ فَارْقُدْ، فَإِنِ اسْتَيْقَظَ فَذَكَرَ اللَّهَ انْحَلَّتْ عُقْدَةٌ، فَإِنْ تَوَضَّأَ انْحَلَّتْ عُقْدَةٌ، فَإِنْ صَلَّى انْحَلَّتْ عُقْدَةٌ؛ فَأَصْبَحَ نَشِيطًا طَيِّبَ النَّفْسِ، وَإِلَّا أَصْبَحَ خَبِيثَ النَّفْسِ كَسْلَانَ». `,
56: `قَالَ النَّبِيُّ ﷺ: «إِذَا رَأَى أَحَدُكُمْ رُؤْيَا يُحِبُّهَا؛ فَإِنَّمَا هِيَ مِنَ اللَّهِ، فَلْيَحْمَدِ اللَّهَ عَلَيْهَا، وَلْيُحَدِّثْ بِهَا». `,
57: `قَالَ النَّبِيُّ ﷺ: «الرُّؤْيَا الْحَسَنَةُ مِنَ اللَّهِ، فَإِذَا رَأَى أَحَدُكُمْ مَا يُحِبُّ فَلَا يُحَدِّثْ بِهِ إِلَّا مَنْ يُحِبُّ. وَإِذَا رَأَى مَا يَكْرَهُ فَلْيَتَعَوَّذْ بِاللَّهِ مِنْ شَرِّهَا، وَمِنْ شَرِّ الشَّيْطَانِ، وَلْيَتْفِلْ ثَلَاثًا، وَلَا يُحَدِّثْ بِهَا أَحَدًا، فَإِنَّهَا لَنْ تَضُرَّهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا رَأَى أَحَدُكُمْ شَيْئًا يَكْرَهُهُ؛ فَلْيَنْفُثْ عَنْ يَسَارِهِ -ثَلَاثَ مَرَّاتٍ-، وَلْيَتَعَوَّذْ بِاللَّهِ مِنْ شَرِّهَا، فَإِنَّهَا لَنْ تَضُرَّهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «وَلْيَتَحَوَّلْ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ».<br><br>قَالَ النَّبِيُّ ﷺ: «فَإِنْ رَأَى أَحَدُكُمْ مَا يَكْرَهُ؛ فَلْيَقُمْ فَلْيُصَلِّ». `,
58: `قَالَ النَّبِيُّ ﷺ: «قُلْ: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾، وَالمُعَوِّذَتَيْنِ، حِينَ تُمْسِي وَتُصْبِحُ -ثَلَاثَ مَرَّاتٍ-؛ تَكْفِيكَ مِنْ كُلِّ شَيْءٍ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ إِذَا أَمْسَى -ثَلَاثَ مَرَّاتٍ-: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ؛ لَمْ تَضُرَّهُ حُمَةٌ تِلْكَ اللَّيْلَةَ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَا مِنْ عَبْدٍ يَقُولُ فِي صَبَاحِ كُلِّ يَوْمٍ وَمَسَاءِ كُلِّ لَيْلَةٍ: بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلَا فِي السَّمَاءِ، وَهُوَ السَّمِيعُ العَلِيمُ -ثَلَاثَ مَرَّاتٍ-؛ فَيَضُرَّهُ شَيْءٌ».<br><br>كَانَ النَّبِيُّ ﷺ إِذَا أَصْبَحَ وَإِذَا أَمْسَى يَقُولُ: «أَصْبَحْنَا عَلَى فِطْرَةِ الإِسْلَامِ، وَعَلَى كَلِمَةِ الإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا، وَمَا كَانَ مِنَ المُشْرِكِينَ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَا مِنْ عَبْدٍ مُسْلِمٍ يَقُولُ حِينَ يُصْبِحُ وَحِينَ يُمْسِي -ثَلَاثَ مَرَّاتٍ-: رَضِيتُ بِاللَّهِ رَبًّا، وَبِالإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ ﷺ نَبِيًّا؛ إِلَّا كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ يَوْمَ القِيَامَةِ».<br><br>كَانَ النَّبِيُّ ﷺ إِذَا أَصْبَحَ قَالَ: «اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ». وَإِذَا أَمْسَى قَالَ: «اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ المَصِيرُ».<br><br>كَانَ النَّبِيُّ ﷺ إِذَا أَمْسَى قَالَ: «أَمْسَيْنَا وَأَمْسَى المُلْكُ لِلَّهِ، وَالحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ، وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ، وَشَرِّ مَا بَعْدَهَا. رَبِّ أَعُوذُ بِكَ مِنَ الكَسَلِ وَسُوءِ الكِبَرِ. رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي القَبْرِ». وَإِذَا أَصْبَحَ قَالَ ذَلِكَ أَيْضًا: «أَصْبَحْنَا، وَأَصْبَحَ المُلْكُ لِلَّهِ ...».<br><br>قَالَ أَبُو بَكْرٍ رضي الله عنه: يَا رَسُولَ اللَّهِ، مُرْنِي بِشَيْءٍ أَقُولُهُ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ. قَالَ: «قُلْ: اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ». قَالَ: «قُلْهُ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ، وَإِذَا أَخَذْتَ مَضْجَعَكَ».<br><br>لَمْ يَكُنِ النَّبِيُّ ﷺ يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: «اللَّهُمَّ إِنِّي أَسْأَلُكَ العَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ. اللَّهُمَّ إِنِّي أَسْأَلُكَ العَفْوَ وَالعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي. اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي. اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي».<br><br>قَالَ النَّبِيُّ ﷺ: «سَيِّدُ الِاسْتِغْفَارِ أَنْ تَقُولَ: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ». قَالَ: «مَنْ قَالَهَا مِنَ النَّهَارِ مُوقِنًا بِهَا، فَمَاتَ مِنْ يَوْمِهِ قَبْلَ أَنْ يُمْسِيَ؛ فَهُوَ مِنْ أَهْلِ الجَنَّةِ. وَمَنْ قَالَهَا مِنَ اللَّيْلِ وَهُوَ مُوقِنٌ بِهَا، فَمَاتَ قَبْلَ أَنْ يُصْبِحَ؛ فَهُوَ مِنْ أَهْلِ الجَنَّةِ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، مِئَةَ مَرَّةٍ؛ لَمْ يَأْتِ أَحَدٌ يَوْمَ القِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ، أَوْ زَادَ عَلَيْهِ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، مِئَةَ مَرَّةٍ إِذَا أَصْبَحَ، وَمِئَةَ مَرَّةٍ إِذَا أَمْسَى؛ لَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِنْهُ، إِلَّا مَنْ قَالَ أَفْضَلَ مِنْ ذَلِكَ».`,
59: `كَانَ النَّبِيُّ ﷺ يُعَوِّذُ الحَسَنَ وَالحُسَيْنَ رضي الله عنهما، وَيَقُولُ: «إِنَّ أَبَاكُمَا كَانَ يُعَوِّذُ بِهَا إِسْمَاعِيلَ وَإِسْحَاقَ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ».`,
60: `قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ: سُبْحَانَ اللَّهِ العَظِيمِ وَبِحَمْدِهِ؛ غُرِسَتْ لَهُ نَخْلَةٌ فِي الجَنَّةِ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، فِي يَوْمٍ مِئَةَ مَرَّةٍ؛ حُطَّتْ خَطَايَاهُ، وَإِنْ كَانَتْ مِثْلَ زَبَدِ البَحْرِ».<br><br>قَالَ النَّبِيُّ ﷺ: «أَحَبُّ الكَلَامِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ».<br><br>قَالَ النَّبِيُّ ﷺ: «كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي المِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ العَظِيمِ».<br><br>قَالَ النَّبِيُّ ﷺ: «أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ؟» قِيلَ: كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: «يُسَبِّحُ مِئَةَ تَسْبِيحَةٍ؛ فَيُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ، أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ».<br><br>عَنْ جُوَيْرِيَةَ رضي الله عنها: أَنَّ النَّبِيَّ ﷺ خَرَجَ مِنْ عِنْدِهَا بُكْرَةً حِينَ صَلَّى الصُّبْحَ وَهِيَ فِي مَسْجِدِهَا، ثُمَّ رَجَعَ بَعْدَ أَنْ أَضْحَى وَهِيَ جَالِسَةٌ، فَقَالَ: «مَا زِلْتِ عَلَى الحَالِ الَّتِي فَارَقْتُكِ عَلَيْهَا؟» قَالَتْ: نَعَمْ. قَالَ: «لَقَدْ قُلْتُ بَعْدَكِ أَرْبَعَ كَلِمَاتٍ -ثَلَاثَ مَرَّاتٍ-، لَوْ وُزِنَتْ بِمَا قُلْتِ مُنْذُ اليَوْمِ لَوَزَنَتْهُنَّ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ».`,
61: `قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، فِي يَوْمٍ مِئَةَ مَرَّةٍ، كَانَتْ لَهُ عِدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِئَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِئَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلَّا رَجُلٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، عَشْرَ مِرَارٍ؛ كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ إِسْمَاعِيلَ».`,
62: `قَالَ النَّبِيُّ ﷺ: «أَلَا أَدُلُّكَ عَلَى كَلِمَةٍ هِيَ كَنْزٌ مِنْ كُنُوزِ الجَنَّةِ؟ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ».`,
63: `قَالَ النَّبِيُّ ﷺ: «إِنِّي لَأَسْتَغْفِرُ اللَّهَ فِي اليَوْمِ مِئَةَ مَرَّةٍ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَا مِنْ رَجُلٍ يُذْنِبُ ذَنْبًا، فَيَتَوَضَّأُ، فَيُحْسِنُ الوُضُوءَ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ، فَيَسْتَغْفِرُ اللَّهَ؛ إِلَّا غَفَرَ لَهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «يَا أَيُّهَا النَّاسُ، تُوبُوا إِلَى اللَّهِ، فَإِنِّي أَتُوبُ فِي اليَوْمِ إِلَيْهِ مِئَةَ مَرَّةٍ».`,
64: `كَانَ النَّبِيُّ ﷺ إِذَا عَصَفَتِ الرِّيحُ قَالَ: «اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ».`,
65: `كَانَ النَّبِيُّ ﷺ إِذَا رَأَى المَطَرَ قَالَ: «اللَّهُمَّ صَيِّبًا نَافِعًا».<br><br>قَالَ النَّبِيُّ ﷺ: «قَالَ اللَّهُ تَعَالَى: أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ؛ فَأَمَّا مَنْ قَالَ: مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ؛ فَذَلِكَ مُؤْمِنٌ بِي كَافِرٌ بِالكَوْكَبِ، وَأَمَّا مَنْ قَالَ: مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا؛ فَذَلِكَ كَافِرٌ بِي مُؤْمِنٌ بِالكَوْكَبِ».`,
66: `قَالَ النَّبِيُّ ﷺ: «إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ؛ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ؛ فَإِنَّهَا رَأَتْ مَلَكًا. وَإِذَا سَمِعْتُمْ نَهِيقَ الحِمَارِ؛ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيْطَانِ؛ فَإِنَّهَا رَأَتْ شَيْطَانًا».`,
67: `قَالَ النَّبِيُّ ﷺ: «مَنْ نَزَلَ مَنْزِلًا، ثُمَّ قَالَ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ؛ لَمْ يَضُرَّهُ شَيْءٌ، حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ».`,
68: `عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه قَالَ: كُنْتُ جَالِسًا عِنْدَ رَسُولِ اللَّهِ ﷺ إِذْ مَرَّ رَجُلٌ، فَقَالَ رَجُلٌ مِنَ القَوْمِ: يَا رَسُولَ اللَّهِ، إِنِّي لَأُحِبُّ هَذَا الرَّجُلَ. قَالَ: «هَلْ أَعْلَمْتَهُ ذَلِكَ؟» قَالَ: لَا. فَقَالَ: «قُمْ فَأَعْلِمْهُ». فَقَامَ إِلَيْهِ، فَقَالَ: يَا هَذَا، وَاللَّهِ إِنِّي لَأُحِبُّكَ فِي اللَّهِ. قَالَ: «أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ».`,
69: `قَالَ النَّبِيُّ ﷺ: «إِذَا رَأَى أَحَدُكُمْ مِنْ أَخِيهِ مَا يُعْجِبُهُ؛ فَلْيَدْعُ لَهُ بِالبَرَكَةِ».`,
70: `عِنْدَ التَّعَجُّبِ مِنْ شَيْءٍ يَقُولُ: «سُبْحَانَ اللَّهِ». وَيَقُولُ: «اللَّهُ أَكْبَرُ».`,
71: `قَالَ النَّبِيُّ ﷺ: «إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلْ: الحَمْدُ لِلَّهِ. وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: يَرْحَمُكَ اللَّهُ. فَإِذَا قَالَ لَهُ: يَرْحَمُكَ اللَّهُ، فَلْيَقُلْ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ».`,
72: `اسْتَبَّ رَجُلَانِ عِنْدَ النَّبِيِّ ﷺ، فَجَعَلَ أَحَدُهُمَا يَغْضَبُ وَيَحْمَرُّ وَجْهُهُ، فَنَظَرَ إِلَيْهِ النَّبِيُّ ﷺ، فَقَالَ: «إِنِّي لَأَعْلَمُ كَلِمَةً لَوْ قَالَهَا لَذَهَبَ عَنْهُ مَا يَجِدُ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ».`,
73: `قَالَ النَّبِيُّ ﷺ: «مَنْ صُنِعَ إِلَيْهِ مَعْرُوفٌ فَقَالَ لِفَاعِلِهِ: جَزَاكَ اللَّهُ خَيْرًا؛ فَقَدْ أَبْلَغَ فِي الثَّنَاءِ».`,
74: `قَالَ النَّبِيُّ ﷺ: «مَنْ جَلَسَ فِي مَجْلِسٍ فَكَثُرَ فِيهِ لَغَطُهُ، فَقَالَ قَبْلَ أَنْ يَقُومَ مِنْ مَجْلِسِهِ ذَلِكَ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ؛ إِلَّا غُفِرَ لَهُ مَا كَانَ فِي مَجْلِسِهِ ذَلِكَ».`,
75: `قَالَ النَّبِيُّ ﷺ: قَالَ اللَّهُ تَعَالَى: «أَنَا أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ، مَنْ عَمِلَ عَمَلًا أَشْرَكَ فِيهِ مَعِيَ غَيْرِي تَرَكْتُهُ وَشِرْكَهُ».<br><br>عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رضي الله عنه: أَنَّ النَّبِيَّ ﷺ قَالَ: «أَلَا أُخْبِرُكُمْ بِمَا هُوَ أَخْوَفُ عَلَيْكُمْ عِنْدِي مِنَ المَسِيحِ الدَّجَّالِ؟» قَالُوا: بَلَى. فَقَالَ: «الشِّرْكُ الخَفِيُّ: أَنْ يَقُومَ الرَّجُلُ يُصَلِّي، فَيُزَيِّنَ صَلَاتَهُ لِمَا يَرَى مِنْ نَظَرِ رَجُلٍ».`,
76: `قَالَ النَّبِيُّ ﷺ: «اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ» (1) .`,
77: `قَالَ النَّبِيُّ ﷺ: «يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ، يَقُولُ: دَعَوْتُ، فَلَمْ يُسْتَجَبْ لِي» (1) .`,
78: `١ - عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: «لَعَنَ النَّبِيُّ ﷺ المُصَوِّرَ» (1) .<br><br>٢ - قَالَ النَّبِيُّ ﷺ: «كُلُّ مُصَوِّرٍ فِي النَّارِ، يَجْعَلُ لَهُ بِكُلِّ صُورَةٍ صَوَّرَهَا نَفْساً، فَتُعَذِّبُهُ فِي جَهَنَّمَ» (2) .`,
79: `قَالَ النَّبِيُّ ﷺ: «تَعَاهَدُوا هَذَا القُرْآنَ، فَوَالَّذِي نَفْسِي بِيَدِهِ، لَهُوَ أَشَدُّ تَفَلُّتًا مِنَ الإِبِلِ فِي عُقُلِهَا»`,
80: `أَتَى النَّبِيُّ ﷺ رَجُلٌ أَعْمَى فَقَالَ: يَا رَسُولَ اللَّهِ؛ إِنَّهُ لَيْسَ لِي قَائِدٌ يَقُودُنِي إِلَى الْمَسْجِدِ، فَسَأَلَ النَّبِيَّ ﷺ أَنْ يُرَخِّصَ لَهُ، فَيُصَلِّيَ فِي بَيْتِهِ، فَرَخَّصَ لَهُ، فَلَمَّا وَلَّى، دَعَاهُ، فَقَالَ: «هَلْ تَسْمَعُ النِّدَاءَ بِالصَّلَاةِ؟»، قَالَ: نَعَمْ، قَالَ: «فَأَجِبْ».`,
81: `قَالَ النَّبِيُّ ﷺ: «إِذَا أَتَيْتُمُ الصَّلَاةَ؛ فَعَلَيْكُمُ السَّكِينَةَ».`,
82: `قَالَ النَّبِيُّ ﷺ: «كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى»، قَالُوا: يَا رَسُولَ اللَّهِ؛ وَمَنْ يَأْبَى؟ قَالَ: «مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى».<br><br>قَالَ النَّبِيُّ ﷺ: «لَا يُؤْمِنُ أَحَدُكُمْ، حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ رَغِبَ عَنْ سُنَّتِي؛ فَلَيْسَ مِنِّي».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا؛ فَهُوَ رَدٌّ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ صَلَّى عَلَيَّ صَلَاةً؛ صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا».`,
83: `قال النبي صلى الله عليه وسلم: خير الناس قرني ثم الذين يلونهم ثم الذين يلونهم. وقال النبي صلى الله عليه وسلم: لو ان احدكم انفق مثل احد ذهبا ما بلغ مد احدهم ولا نصيفه.`,
84: `جَاءَ رَجُلٌ إِلَى النَّبِيِّ ﷺ فَقَالَ: مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ». قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ».<br><br>قَالَ النَّبِيُّ ﷺ: «أَبَرُّ الْبِرِّ: أَنْ يَصِلَ الرَّجُلُ وُدَّ أَبِيهِ».`,
85: `قَالَ النَّبِيُّ ﷺ: «مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ؛ فَلْيَصِلْ رَحِمَهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا».<br><br>قَالَ النَّبِيُّ ﷺ: «لَا يَدْخُلُ الْجَنَّةَ قَاطِعُ رَحِمٍ».`,
86: `قَالَ النَّبِيُّ ﷺ: «مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ، حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ؛ فَلْيُكْرِمْ جَارَهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ؛ فَلَا يُؤْذِ جَارَهُ».`,
87: `قَالَ النَّبِيُّ ﷺ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ؛ فَلْيُكْرِمْ ضَيْفَهُ».`,
88: `قَالَ النَّبِيُّ ﷺ: «إِنَّ اللَّهَ قَالَ: مَنْ عَادَى لِي وَلِيًّا؛ فَقَدْ آذَنْتُهُ بِالْحَرْبِ».`,
89: `تَكَلَّمَ رَجُلٌ فِي حَضْرَةِ مَنْ هُوَ أَكْبَرُ مِنْهُ، فَقَالَ النَّبِيُّ ﷺ: «لِيَبْدَأَ الْأَكْبَرُ».`,
90: `قَالَ النَّبِيُّ ﷺ: «مَنْ عَادَ مَرِيضًا لَمْ يَزَلْ فِي خُرْفَةِ الْجَنَّةِ حَتَّى يَرْجِعَ»، قِيلَ: يَا رَسُولَ اللَّهِ؛ وَمَا خُرْفَةُ الْجَنَّةِ؟ قَالَ: «جَنَاهَا».`,
91: `قَالَ النَّبِيُّ ﷺ: «اتَّقُوا اللَّعَّانَيْنِ»، قَالُوا: وَمَا اللَّعَّانَانِ يَا رَسُولَ اللَّهِ؟ قَالَ: «الَّذِي يَتَخَلَّى فِي طَرِيقِ النَّاسِ، أَوْ فِي ظِلِّهِمْ».<br><br>قَالَ النَّبِيُّ ﷺ: «لَا يُمْسِكَنَّ أَحَدُكُمْ ذَكَرَهُ بِيَمِينِهِ وَهُوَ يَبُولُ، وَلَا يَتَمَسَّحْ مِنَ الْخَلَاءِ بِيَمِينِهِ».<br><br>مَرَّ النَّبِيُّ ﷺ عَلَى قَبْرَيْنِ فَقَالَ: «أَمَا إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ؛ أَمَّا أَحَدُهُمَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ، وَأَمَّا الْآخَرُ فَكَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ».`,
92: `قَالَ النَّبِيُّ ﷺ: «خَمْسٌ مِنَ الْفِطْرَةِ: الْخِتَانُ، وَالِاسْتِحْدَادُ، وَتَقْلِيمُ الْأَظْفَارِ، وَنَتْفُ الْإِبِطِ، وَقَصُّ الشَّارِبِ».<br><br>قَالَ أَنَسٌ رضي الله عنه: وُقِّتَ لَنَا فِي قَصِّ الشَّارِبِ، وَتَقْلِيمِ الْأَظْفَارِ، وَنَتْفِ الْإِبْطِ، وَحَلْقِ الْعَانَةِ، أَلَّا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ لَيْلَةً.`,
93: `قَالَ النَّبِيُّ ﷺ: «السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ، مَرْضَاةٌ لِلرَّبِّ».<br><br>قَالَ النَّبِيُّ ﷺ: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي، لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ».`,
94: `كَانَ النَّبِيُّ ﷺ إِذَا عَطَسَ؛ غَطَّى وَجْهَهُ بِيَدِهِ أَوْ ثَوْبِهِ، وَغَضَّ بِهَا صَوْتَهُ.`,
95: `قَالَ النَّبِيُّ ﷺ: «التَّثَاؤُبُ مِنَ الشَّيْطَانِ، فَإِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَرُدَّهُ مَا اسْتَطَاعَ، فَإِنَّ أَحَدَكُمْ إِذَا قَالَ: (هَا)، ضَحِكَ الشَّيْطَانُ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيُمْسِكْ بِيَدِهِ عَلَى فِيهِ، فَإِنَّ الشَّيْطَانَ يَدْخُلُ».`,
96: `قَالَ النَّبِيُّ ﷺ: «مَا أَسْفَلَ مِنَ الْكَعْبَيْنِ مِنَ الْإِزَارِ؛ فَفِي النَّارِ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ جَرَّ ثَوْبَهُ خُيَلَاءَ؛ لَمْ يَنْظُرِ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ».`,
97: `قَالَ النَّبِيُّ ﷺ: «إِذَا انْتَعَلَ أَحَدُكُمْ فَلْيَبْدَأْ بِالْيَمِينِ، وَإِذَا نَزَعَ فَلْيَبْدَأْ بِالشِّمَالِ».<br><br>قَالَ النَّبِيُّ ﷺ: «لَا يَمْشِي أَحَدُكُمْ فِي نَعْلٍ وَاحِدَةٍ؛ لِيُنْعِلْهُمَا جَمِيعًا، أَوْ لِيَخْلَعْهُمَا جَمِيعًا».`,
98: `قَالَ النَّبِيُّ ﷺ: «خَالِفُوا الْمُشْرِكِينَ: وَفِّرُوا اللِّحَى، وَأَحْفُوا الشَّوَارِبَ».`,
99: `نهي النبي صلي الله عليه وسلم عن القزع`,
100: `قَالَ النَّبِيُّ ﷺ: «لَعَنَ اللَّهُ الْوَاصِلَةَ، وَالْمُسْتَوْصِلَةَ، وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ».<br><br>قَالَ ابْنُ مَسْعُودٍ رضي الله عنه: لَعَنَ اللَّهُ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ، وَالنَّامِصَاتِ وَالْمُتَنَمِّصَاتِ، وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ، الْمُغَيِّرَاتِ خَلْقَ اللَّهِ، وَمَا لِي لَا أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ ﷺ.`,
101: `قَالَ النَّبِيُّ ﷺ: «مَنْ تَشَبَّهَ بِقَوْمٍ؛ فَهُوَ مِنْهُمْ».<br><br>عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَعَنَ رَسُولُ اللَّهِ ﷺ الْمُتَشَبِّهِينَ مِنَ الرِّجَالِ بِالنِّسَاءِ، وَالْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ.`,
102: `قَالَ النَّبِيُّ ﷺ: «يَا غُلَامُ؛ سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ».<br><br>قَالَ النَّبِيُّ ﷺ: «كُلُوا فِي الْقَصْعَةِ مِنْ جَوَانِبِهَا، وَلَا تَأْكُلُوا مِنْ وَسَطِهَا؛ فَإِنَّ الْبَرَكَةَ تَنْزِلُ فِي وَسَطِهَا».<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا وَقَعَتْ لُقْمَةُ أَحَدِكُمْ فَلْيَأْخُذْهَا، فَلْيُمِطْ مَا كَانَ بِهَا مِنْ أَذًى وَلْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ».<br><br>مَا عَابَ رَسُولُ اللَّهِ ﷺ طَعَامًا قَطُّ، إِنِ اشْتَهَاهُ أَكَلَهُ، وَإِنْ كَرِهَهُ تَرَكَهُ.`,
103: `نَهَى النَّبِيُّ ﷺ عَنِ الشُّرْبِ قَائِمًا.<br><br>نَهَى النَّبِيُّ ﷺ عَنِ النَّفْخِ فِي الطَّعَامِ وَالشَّرَابِ.<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا شَرِبَ أَحَدُكُمْ؛ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ».<br><br>كَانَ النَّبِيُّ ﷺ يَتَنَفَّسُ فِي الشُّرْبِ ثَلَاثًا.`,
104: `أَمَرَ رَسُولُ اللَّهِ ﷺ بِلَعْقِ الْأَصَابِعِ وَالصَّحْفَةِ، وَقَالَ: «إِنَّكُمْ لَا تَدْرُونَ فِي أَيِّهِ الْبَرَكَةُ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا، أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا».`,
105: `قَالَ النَّبِيُّ ﷺ: «الْإِيمَانُ بِضْعٌ وَسَبْعُونَ - أَوْ: بِضْعٌ وَسِتُّونَ - شُعْبَةً، فَأَفْضَلُهَا قَوْلُ: لَا إِلَهَ إِلَّا اللَّهُ، وَأَدْنَاهَا: إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ».<br><br>عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رضي الله عنه: أَنَّ النَّبِيَّ ﷺ قَالَ: «إِيَّاكُمْ وَالْجُلُوسَ بِالطُّرُقَاتِ»، فَقَالُوا: يَا رَسُولَ اللَّهِ؛ مَا لَنَا بُدٌّ مِنْ مَجَالِسِنَا نَتَحَدَّثُ فِيهَا. قَالَ رَسُولُ اللَّهِ ﷺ: «إِذَا أَبَيْتُمْ إِلَّا الْمَجْلِسَ، فَأَعْطُوا الطَّرِيقَ حَقَّهُ»، قَالُوا: وَمَا حَقُّهُ؟ قَالَ: «غَضُّ الْبَصَرِ، وَكَفُّ الْأَذَى، وَرَدُّ السَّلَامِ، وَالْأَمْرُ بِالْمَعْرُوفِ، وَالنَّهْيُ عَنِ الْمُنْكَرِ».`,
106: `قَالَ النَّبِيُّ ﷺ: «لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ».<br><br>سُئِلَ النَّبِيُّ ﷺ: أَيُّ الْإِسْلَامِ خَيْرٌ؟ قَالَ: «تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ».`,
107: `قَالَ النَّبِيُّ ﷺ: «إِنَّمَا جُعِلَ الِاسْتِئْذَانُ مِنْ أَجْلِ الْبَصَرِ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِذَا اسْتَأْذَنَ أَحَدُكُمْ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ؛ فَلْيَرْجِعْ».`,
108: `قَالَ النَّبِيُّ ﷺ: «إِذَا أَطَالَ أَحَدُكُمُ الْغَيْبَةَ؛ فَلَا يَطْرُقْ أَهْلَهُ لَيْلًا».`,
109: `قَالَ النَّبِيُّ ﷺ: «لَا يُقِيمَنَّ الرَّجُلُ الرَّجُلَ مِنْ مَقْعَدِهِ، ثُمَّ يَجْلِسُ فِيهِ، وَلَكِنْ تَفَسَّحُوا وَتَوَسَّعُوا».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ قَامَ مِنْ مَجْلِسِهِ، ثُمَّ رَجَعَ إِلَيْهِ؛ فَهُوَ أَحَقُّ بِهِ».`,
110: `قَالَ النَّبِيُّ ﷺ: «مَنْ اسْتَمَعَ إِلَى حَدِيثِ قَوْمٍ وَهُمْ لَهُ كَارِهُونَ، أَوْ يَفِرُّونَ مِنْهُ؛ صُبَّ فِي أُذُنِهِ الْآنُكُ يَوْمَ الْقِيَامَةِ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَثَلُ الْجَلِيسِ الصَّالِحِ وَالسَّوْءِ؛ كَحَامِلِ الْمِسْكِ وَنَافِخِ الْكِيرِ. فَحَامِلُ الْمِسْكِ: إِمَّا أَنْ يُحْذِيَكَ، وَإِمَّا أَنْ تَبْتَاعَ مِنْهُ، وَإِمَّا أَنْ تَجِدَ مِنْهُ رِيحًا طَيِّبَةً. وَنَافِخُ الْكِيرِ: إِمَّا أَنْ يُحْرِقَ ثِيَابَكَ، وَإِمَّا أَنْ تَجِدَ رِيحًا خَبِيثَةً».`,
111: `أُثْنِيَ رَجُلٌ عَلَى رَجُلٍ عِنْدَ النَّبِيِّ ﷺ، فَقَالَ: «وَيْلَكَ! قَطَعْتَ عُنُقَ صَاحِبِكَ، قَطَعْتَ عُنُقَ صَاحِبِكَ» -مِرَارًا-، «مَنْ كَانَ مِنْكُمْ مَادِحًا أَخَاهُ لَا مَحَالَةَ؛ فَلْيَقُلْ: أَحْسِبُ فُلَانًا وَاللَّهُ حَسِيبُهُ، وَلَا أُزَكِّي عَلَى اللَّهِ أَحَدًا، أَحْسِبُهُ كَذَا وَكَذَا -إِنْ كَانَ يَعْلَمُ ذَلِكَ مِنْهُ-».`,
112: `قَالَ النَّبِيُّ ﷺ: «بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ».`,
113: `قَالَ النَّبِيُّ ﷺ: «إِذَا كُنْتُمْ ثَلَاثَةً، فَلَا يَتَنَاجَى اثْنَانِ دُونَ صَاحِبِهِمَا؛ فَإِنَّ ذَلِكَ يُحْزِنُهُ».`,
114: `قَالَ النَّبِيُّ ﷺ: «لَيَكُونَنَّ مِنْ أُمَّتِي أَقْوَامٌ يَسْتَحِلُّونَ: الْحِرَ وَالْحَرِيرَ، وَالْخَمْرَ، وَالْمَعَازِفَ».`,
115: `قَالَ النَّبِيُّ ﷺ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ؛ فَلْيَقُلْ خَيْرًا، أَوْ لِيَصْمُتْ».<br><br>قَالَ النَّبِيُّ ﷺ: «مَنْ يَضْمَنْ لِي مَا بَيْنَ لِحْيَيْهِ، وَمَا بَيْنَ رِجْلَيْهِ؛ أَضْمَنْ لَهُ الْجَنَّةَ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ، مَا يَتَبَيَّنُ فِيهَا، يَهْوِي بِهَا فِي النَّارِ أَبْعَدَ مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ».`,
116: `قَالَ النَّبِيُّ ﷺ: «عَلَيْكُمْ بِالصِّدْقِ، فَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ وَيَتَحَرَّى الصِّدْقَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا. وَإِيَّاكُمْ وَالْكَذِبَ، فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَمَا يَزَالُ الرَّجُلُ يَكْذِبُ وَيَتَحَرَّى الْكَذِبَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا».`,
117: `قَالَ النَّبِيُّ ﷺ: «الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ».`,
118: `قَالَ النَّبِيُّ ﷺ: «سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ».<br><br>قَالَ النَّبِيُّ ﷺ: «لَعْنُ الْمُؤْمِنِ كَقَتْلِهِ».<br><br>قَالَ النَّبِيُّ ﷺ: «إِنَّ اللَّعَّانِينَ لَا يَكُونُونَ شُهَدَاءَ، وَلَا شُفَعَاءَ يَوْمَ الْقِيَامَةِ».`,
119: `قَالَ النَّبِيُّ ﷺ: «كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ، وَمَالُهُ، وَعِرْضُهُ».<br><br>عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قُلْتُ لِلنَّبِيِّ ﷺ: حَسْبُكَ مِنْ صَفِيَّةَ كَذَا وَكَذَا -تَعْنِي: قَصِيرَةً-، فَقَالَ: «لَقَدْ قُلْتِ كَلِمَةً لَوْ مُزِجَتْ بِمَاءِ الْبَحْرِ لَمَزَجَتْهُ».<br><br>قَالَ النَّبِيُّ ﷺ: «لَمَّا عُرِجَ بِي؛ مَرَرْتُ بِقَوْمٍ لَهُمْ أَظْفَارٌ مِنْ نُحَاسٍ يَخْمُشُونَ وُجُوهَهُمْ وَصُدُورَهُمْ، فَقُلْتُ: مَنْ هَؤُلَاءِ يَا جِبْرِيلُ؟ قَالَ: هَؤُلَاءِ الَّذِينَ يَأْكُلُونَ لُحُومَ النَّاسِ، وَيَقَعُونَ فِي أَعْرَاضِهِمْ».`,
120: `قَالَ النَّبِيُّ ﷺ: «لَا يَدْخُلُ الْجَنَّةَ نَمَّامٌ».`,
121: `قَالَ النَّبِيُّ ﷺ: «وَيْلٌ لِلَّذِي يُحَدِّثُ فَيَكْذِبُ؛ لِيُضْحِكَ بِهِ الْقَوْمَ، وَيْلٌ لَهُ! وَيْلٌ لَهُ!».`,
122: `قَالَ النَّبِيُّ ﷺ: «إِنَّ مِنْ خِيَارِكُمْ؛ أَحَاسَنَكُمْ أَخْلَاقًا».<br><br>قَالَ النَّبِيُّ ﷺ: «أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا؛ أَحْسَنُهُمْ خُلُقًا».<br><br>قَالَ النَّبِيُّ ﷺ: «مَا شَيْءٌ أَثْقَلَ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ؛ مِنْ خُلُقٍ حَسَنٍ».`,
123: `قَالَ النَّبِيُّ ﷺ: «لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا، وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ».`,
124: `قَالَ النَّبِيُّ ﷺ: «مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللَّهُ».`,
125: `قَالَ النَّبِيُّ ﷺ: «لَا يُؤْمِنُ أَحَدُكُمْ؛ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ».`,
126: `قَالَ النَّبِيُّ ﷺ: «مَنْ دَلَّ عَلَى خَيْرٍ؛ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ».`,
127: `قَالَ النَّبِيُّ ﷺ: «لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ».`,
128: `قَالَ النَّبِيُّ ﷺ: «لَا تَبَاغَضُوا، وَلَا تَحَاسَدُوا، وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا».`,
129: `قَالَ النَّبِيُّ ﷺ: «إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ».`,
130: `قَالَ النَّبِيُّ ﷺ: «لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثِ لَيَالٍ -يَلْتَقِيَانِ، فَيُعْرِضُ هَذَا، وَيُعْرِضُ هَذَا-، وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلَامِ».`,
131: `قَالَ النَّبِيُّ ﷺ: «إِنَّ شَرَّ النَّاسِ: ذُو الْوَجْهَيْنِ؛ الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ، وَهَؤُلَاءِ بِوَجْهٍ».`,
132: `قَالَ النَّبِيُّ ﷺ: «مَنْ غَشَّنَا؛ فَلَيْسَ مِنَّا».`,
133: `قَالَ النَّبِيُّ ﷺ: «مَنْ سَأَلَ النَّاسَ أَمْوَالَهُمْ تَكَثُّرًا؛ فَإِنَّمَا يَسْأَلُ جَمْرًا، فَلْيَسْتَقِلَّ أَوْ لِيَسْتَكْثِرْ».`,
134: `قَالَ النَّبِيُّ ﷺ: «الْحَيَاءُ كُلُّهُ خَيْرٌ».`,
135: `قَالَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا: يَرْحَمُ اللَّهُ نِسَاءَ الْمُهَاجِرَاتِ الْأُوَلَ، لَمَّا نَزَلَتْ: ﴿وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ﴾؛ شَقَقْنَ مُرُوطَهُنَّ، فَاخْتَمَرْنَ بِهَا.`,
136: `قَالَ النَّبِيُّ ﷺ: «لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ، وَلَا تُسَافِرَنَّ امْرَأَةٌ إِلَّا وَمَعَهَا مَحْرَمٌ».`,
137: `قَالَ النَّبِيُّ ﷺ: «لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا».`,
138: `قَالَ جَرِيرُ بْنُ عَبْدِ اللَّهِ رضي الله عنه: سَأَلْتُ رَسُولَ اللَّهِ ﷺ عَنْ نَظَرِ الْفَجْأَةِ؛ فَأَمَرَنِي أَنْ أَصْرِفَ بَصَرِي.`,
139: `قَالَ النَّبِيُّ ﷺ: «إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ!»، فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: يَا رَسُولَ اللَّهِ؛ أَفَرَأَيْتَ الْحَمْوَ؟! قَالَ: «الْحَمْوُ الْمَوْتُ».`,
140: `قَالَ النَّبِيُّ ﷺ: «إِنِّي لَا أُصَافِحُ النِّسَاءَ».<br><br>قَالَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا: وَاللَّهِ؛ مَا مَسَّتْ يَدُ رَسُولِ اللَّهِ ﷺ يَدَ امْرَأَةٍ قَطُّ.`,
141: `قَالَ النَّبِيُّ ﷺ: «لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ إِلَّا كَانَ ثَالِثَهُمَا الشَّيْطَانُ».`,
142: `قَالَ النَّبِيُّ ﷺ: «مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ»`,
};


/* ==========================================================
   التفاعل والمنطق البرمجي
========================================================== */

function safeLoad(key, fallback) {
    try { const value = localStorage.getItem(key); return value === null ? fallback : JSON.parse(value); }
    catch (e) { return fallback; }
}
function saveJSON(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { showToast('تعذر حفظ التغييرات في هذا المتصفح'); } }
let currentTopicId = 1;
let savedTopics = safeLoad('savedTopics', []);
let favoriteTopics = safeLoad('favoriteTopics', []);
let bookmarkedTopics = safeLoad('bookmarkedTopics', []);
let reviewRecords = safeLoad('reviewRecords', {});
if (!Array.isArray(savedTopics)) savedTopics = [];
if (!Array.isArray(favoriteTopics)) favoriteTopics = [];
if (!Array.isArray(bookmarkedTopics)) bookmarkedTopics = [];
if (!reviewRecords || typeof reviewRecords !== 'object' || Array.isArray(reviewRecords)) reviewRecords = {};
let isDark = safeLoad('isDark', false) === true;
let lastReadTopic = Number(localStorage.getItem('lastReadTopic')) || 0;
let fontSize = Number(localStorage.getItem('fontSize')) || 21;
let quizTopicId = 0;
let quizAnswerShown = false;
let audioElement = null;
const audioSources = {1:'/1.mp3', 2:'/2.mp3' ,3:'/3.mp3', 4:'/4.mp3'}; // أضف هنا روابط التسجيلات عند توفرها: {1:'audio/1.mp3', 2:'audio/2.mp3'}
let repeatTarget = localStorage.getItem('repeatCount') === null ? 1 : Number(localStorage.getItem('repeatCount'));
let repeatCurrent = 0;
let repeatingAudio = false;


if(isDark) document.body.classList.add('dark');
function syncThemeButton() { const b=document.querySelector('.theme'); if(b){ b.textContent=isDark?'☀️':'🌙'; b.setAttribute('aria-label',isDark?'تفعيل الوضع النهاري':'تفعيل الوضع الليلي'); b.setAttribute('title',isDark?'الوضع النهاري':'الوضع الليلي'); } }
if (document.readyState !== 'loading') syncThemeButton(); else document.addEventListener('DOMContentLoaded', syncThemeButton);

function renderBook() {
    let container = document.getElementById('book');
    let html = '';

    sections.forEach(sec => {
        html += `
        <div class="book-section">
            <div class="section-header">
                <div class="section-icon">${sec.icon}</div>
                <div class="section-info">
                    <h3>${sec.title}</h3>
                    <p>${sec.description}</p>
                </div>
            </div>
        `;

        sec.categories.forEach(cat => {
            html += `
            <div class="category">
                <button type="button" class="category-header category-toggle" onclick="toggleCategory(this)">
                    <span class="category-title"><span class="category-chevron">⌄</span><h4>${cat.title}</h4></span>
                    <span>${cat.topics.length} موضوعات</span>
                </button>
                <div class="topic-list">
            `;

            cat.topics.forEach(t => {
                let id = t[0];
                let name = t[1];
                let isSaved = savedTopics.includes(id);
                let isFav = favoriteTopics.includes(id);
                
                html += `
                <div class="topic-row">
                    <button class="topic" onclick="openTopic(${id})" aria-label="فتح الحديث: ${name}">
                        <span class="number">${id}</span>
                        <span class="topic-name">${name}</span>
                        <span class="topic-status">
                            ${isSaved ? '🧠 ' : ''}
                            ${isFav ? '❤️' : ''}
                        </span>
                    </button>
                    <button type="button" class="topic-listen" onclick="event.stopPropagation(); playRecordedTopicById(${id})" aria-label="سماع الحديث: ${name}" title="سماع الحديث">
                        🔊
                    </button>
                </div>
                `;
            });

            html += `</div></div>`;
        });

        html += `</div>`;
    });

    container.innerHTML = html;
    updateStats();
}

function openTopic(id) {
    currentTopicId = id;
    lastReadTopic = id;
    localStorage.setItem('lastReadTopic', String(id));
    try { localStorage.setItem('lastReadAt', new Date().toISOString()); } catch(e) {}
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('topicPage').classList.add('active');
    window.scrollTo(0, 0);

    let titleText = "";
    sections.forEach(sec => {
        sec.categories.forEach(cat => {
            cat.topics.forEach(t => {
                if(t[0] === id) titleText = t[1];
            });
        });
    });

    document.getElementById('topicHead').innerHTML = `
        <small>الموضوع رقم (${id})</small>
        <h2>${titleText}</h2>
    `;

    let content = topicTexts[id] || `<div class="no-text">عذراً، النص غير متوفر حالياً لهذا الموضوع.</div>`;
    document.getElementById('topicText').innerHTML = content;
    applyFontSize();
    setupAudioForTopic();

    updateActionButtons();
    updateContinueReading();
}

/* دالة التنقل السلس بين الموضوعات والأقسام باستخدام الأسهم */
function navigateTopic(direction) {
    let nextId = currentTopicId + direction;
    if(nextId >= 1 && nextId <= 142) {
        openTopic(nextId);
    }
}

function home() {
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('home').classList.add('active');
    window.scrollTo(0, 0);
    renderBook();
    renderContinueHome();
}

function toggleSave() {
    let index = savedTopics.indexOf(currentTopicId);
    if(index > -1) {
        savedTopics.splice(index, 1);
    } else {
        savedTopics.push(currentTopicId);
    }
    localStorage.setItem('savedTopics', JSON.stringify(savedTopics));
    updateActionButtons();
    updateStats();
    showToast(index > -1 ? 'تمت إزالة الحديث من الحفظ' : 'تمت إضافة الحديث إلى الحفظ');
}

function toggleFavorite() {
    let index = favoriteTopics.indexOf(currentTopicId);
    if(index > -1) {
        favoriteTopics.splice(index, 1);
    } else {
        favoriteTopics.push(currentTopicId);
    }
    localStorage.setItem('favoriteTopics', JSON.stringify(favoriteTopics));
    updateActionButtons();
    updateStats();
    showToast(index > -1 ? 'تمت إزالة الحديث من المفضلة' : 'تمت الإضافة إلى المفضلة');
}

function updateActionButtons() {
    let saveBtn = document.getElementById('saveBtn');
    let favBtn = document.getElementById('favoriteBtn');
    updateBookmarkButton();

    if(savedTopics.includes(currentTopicId)) {
        saveBtn.className = "action active primary";
        saveBtn.innerHTML = "🧠 تمت الإضافة للحفظ";
    } else {
        saveBtn.className = "action primary";
        saveBtn.innerHTML = "🧠 أضف للحفظ";
    }

    if(favoriteTopics.includes(currentTopicId)) {
        favBtn.className = "action active";
        favBtn.innerHTML = "❤️ في المفضلة";
    } else {
        favBtn.className = "action";
        favBtn.innerHTML = "♡ إضافة للمفضلة";
    }
}

function updateStats() {
    let total = 142;
    let saved = new Set(savedTopics).size;
    let fav = new Set(favoriteTopics).size;

    document.getElementById('total').innerText = total;
    document.getElementById('saved').innerText = saved;
    document.getElementById('fav').innerText = fav;

    let percent = Math.round((saved / total) * 100);
    document.getElementById('percentBadge').innerText = percent + "% منجز";
    document.getElementById('fill').style.width = percent + "%";
    const archPercent = document.getElementById('archPercent');
    if (archPercent) archPercent.innerText = percent + "%";
    const arch = document.querySelector('.journey-arch');
    if (arch) arch.style.setProperty('--progress-angle', `${percent * 3.6}deg`);
    // تُحدَّد المرحلة بحسب حدود الكتاب الفعلية وعدد الموضوعات المحفوظة،
    // لا بتقسيم النسبة المئوية إلى عشرة أجزاء متساوية.
    document.querySelectorAll('.journey-stage').forEach((stage) => {
      const start = Number(stage.dataset.start);
      const end = Number(stage.dataset.end);
      const isComplete = saved >= end;
      const isCurrent = saved >= start - 1 && saved < end;
      stage.classList.toggle('stage-current', isCurrent && percent < 100);
      stage.classList.toggle('stage-complete', isComplete || percent === 100);
    });
    document.getElementById('savedCountText').innerText = `${saved} / ${total} موضوعاً`;

    let motivationText = "ابدأ رحلة الحفظ الآن.";
    if(percent > 0 && percent <= 25) motivationText = "بداية ممتازة، استمر في التقدم.";
    else if(percent > 25 && percent <= 50) motivationText = "رائع جدًا، لقد تجاوزت الربع، واصل همتك.";
    else if(percent > 50 && percent <= 75) motivationText = "أنت في منتصف الطريق، واصل التقدم.";
    else if(percent > 75 && percent < 100) motivationText = "لم يتبق سوى القليل لإتمام الحفظ.";
    else if(percent === 100) motivationText = "مبارك، لقد أتممت حفظ جميع الموضوعات بنجاح.";

    document.getElementById('progressMotivation').innerText = motivationText;
}

function showFavorites() {
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('favoritesPage').classList.add('active');
    window.scrollTo(0, 0);

    let container = document.getElementById('favorites');
    if(favoriteTopics.length === 0) {
        container.innerHTML = `<div class="empty"><div class="big">♡</div><h3>لا توجد موضوعات في المفضلة</h3><p>أضف ما يعجبك للوصول إليه سريعاً</p></div>`;
        return;
    }

    let html = '';
    favoriteTopics.forEach(id => {
        let name = "";
        sections.forEach(sec => {
            sec.categories.forEach(cat => {
                cat.topics.forEach(t => {
                    if(t[0] === id) name = t[1];
                });
            });
        });
        html += `<div class="result"><button onclick="openTopic(${id})"><small>الموضوع (${id})</small><strong>${name}</strong></button></div>`;
    });
    container.innerHTML = html;
}

function showMemory() {
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('memoryPage').classList.add('active');
    window.scrollTo(0, 0);
    const container = document.getElementById('memory');
    const dueIds = getDueReviewIds();
    const uniqueSaved = [...new Set(savedTopics)];
    let html = `<div class="review-summary"><strong>${dueIds.length}</strong><span>موضوعًا مستحقًا للمراجعة</span><small>تُحفظ مواعيد المراجعة على هذا الجهاز</small></div>`;
    if (dueIds.length) {
        html += `<h3 class="memory-subheading">حان وقت مراجعتها</h3>`;
        dueIds.forEach(id => { html += memoryRowHtml(id, 'مستحق للمراجعة', true); });
    } else {
        html += `<div class="empty compact-empty"><div class="big">🌿</div><h3>لا توجد مراجعات مستحقة الآن</h3><p>اختبر حفظك في أي موضوع، وستظهر مواعيد المراجعة هنا.</p></div>`;
    }
    html += `<h3 class="memory-subheading">الموضوعات التي أضفتها للحفظ (${uniqueSaved.length})</h3>`;
    if (!uniqueSaved.length) html += `<div class="empty compact-empty"><p>اضغط على «أضف للحفظ» داخل أي موضوع ليظهر هنا.</p></div>`;
    else uniqueSaved.forEach(id => { html += memoryRowHtml(id, reviewRecords[id] ? `آخر اختبار: ${formatReviewDate(reviewRecords[id].lastReviewed)}` : 'لم يُختبر بعد', true); });
    container.innerHTML = html;
}
function memoryRowHtml(id, note, withQuiz) {
    const name = getTopicName(id) || `الموضوع ${id}`;
    return `<div class="result memory-result"><button type="button" onclick="openTopic(${Number(id)})"><small>${escapeHTML(note)}</small><strong>${escapeHTML(name)}</strong></button>${withQuiz ? `<button type="button" class="mini-quiz-button" onclick="memoryTest(${Number(id)})">اختبرني</button>` : ''}</div>`;
}
function getDueReviewIds() {
    const now = Date.now();
    return Object.keys(reviewRecords).map(Number).filter(id => reviewRecords[id] && Number(reviewRecords[id].nextReview || 0) <= now).sort((a,b) => Number(reviewRecords[a].nextReview||0)-Number(reviewRecords[b].nextReview||0));
}
function formatReviewDate(value) {
    if (!value) return 'غير متوفر';
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? 'غير متوفر' : date.toLocaleDateString('ar', {year:'numeric',month:'short',day:'numeric'});
}
function getTopicName(id) {
    for (const sec of sections) for (const cat of sec.categories) for (const topic of cat.topics) if (topic[0] === Number(id)) return topic[1];
    return '';
}
function escapeHTML(value) {
    return String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
}

function renderContinueHome() {
    const box=document.getElementById('continueReading'); if(!box) return;
    if(lastReadTopic) {
        let name=''; sections.forEach(sec=>sec.categories.forEach(cat=>cat.topics.forEach(t=>{if(t[0]===lastReadTopic) name=t[1];})));
        box.hidden=false; box.innerHTML=`<span>📖</span><div><strong>متابعة القراءة</strong><small>${name}</small></div><button onclick="openTopic(${lastReadTopic})">متابعة ←</button>`;
    } else box.hidden=true;
}

function search() {
    const input = document.getElementById('searchInput');
    const q = input.value.trim();
    const field = document.getElementById('searchField')?.value || 'all';
    const filter = document.getElementById('searchFilter')?.value || 'all';
    const resultsContainer = document.getElementById('results');
    const panelOpen = !document.getElementById('advancedSearchPanel')?.hidden;
    if (!q && filter === 'all' && !panelOpen) {
        if (document.getElementById('searchPage').classList.contains('active')) home();
        return;
    }
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('searchPage').classList.add('active');
    const nq = normalizeArabic(q);
    if (!nq && filter === 'all') {
        document.getElementById('searchSummary').textContent = 'اكتب كلمة للبحث، أو اختر تصفية لعرض المحفوظات والمفضلة والمراجعات.';
        resultsContainer.innerHTML = `<div class="empty"><div class="big">⌕</div><h3>بحث أسهل عن موضوعات الكتاب</h3><p>اكتب كلمة أو اختر نوع المحتوى من خيارات البحث.</p></div>`;
        return;
    }
    const matches = [];
    sections.forEach(sec => sec.categories.forEach(cat => cat.topics.forEach(t => {
        const title = normalizeArabic(t[1]);
        const text = normalizeArabic((topicTexts[t[0]] || '').replace(/<[^>]*>/g, ' '));
        const category = normalizeArabic(cat.title + ' ' + sec.title);
        const hay = field === 'title' ? title : field === 'text' ? text : field === 'category' ? category : `${title} ${text} ${category}`;
        if (nq && !hay.includes(nq)) return;
        if (!nq && filter === 'all' && !panelOpen) return;
        if (filter === 'saved' && !savedTopics.includes(t[0])) return;
        if (filter === 'favorites' && !favoriteTopics.includes(t[0])) return;
        if (filter === 'bookmarks' && !bookmarkedTopics.includes(t[0])) return;
        if (filter === 'due' && !getDueReviewIds().includes(t[0])) return;
        matches.push({id:t[0],name:t[1],category:cat.title,section:sec.title});
    })));
    document.getElementById('searchSummary').textContent = `تم العثور على ${matches.length} نتيجة${q ? ` للبحث عن «${q}»` : ''}`;
    if (!matches.length) {
        resultsContainer.innerHTML = `<div class="empty"><div class="big">🔍</div><h3>لم نجد نتائج مطابقة</h3><p>جرّب كلمة أقصر أو غيّر مجال البحث أو التصفية.</p></div>`;
        return;
    }
    resultsContainer.innerHTML = matches.map(m => `<div class="result"><button type="button" onclick="openTopic(${m.id})"><small>${escapeHTML(m.section)} ← ${escapeHTML(m.category)} · موضوع (${m.id})</small><strong>${escapeHTML(m.name)}</strong></button></div>`).join('');
}
function normalizeArabic(text) {
    return String(text || '').toLowerCase()
        .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
        .replace(/[إأآٱ]/g, 'ا')
        .replace(/ة/g, 'ه').replace(/ى/g, 'ي').replace(/ؤ/g, 'و').replace(/ئ/g, 'ي');
}
function clearSearch() {
    document.getElementById('searchInput').value = '';
    const panel = document.getElementById('advancedSearchPanel');
    if (panel) panel.hidden = true;
    const toggle = document.getElementById('advancedSearchToggle');
    if (toggle) toggle.setAttribute('aria-expanded','false');
    if(document.getElementById('searchPage').classList.contains('active')) home();
}
function showAdvancedSearch() {
    const panel = document.getElementById('advancedSearchPanel');
    const toggle = document.getElementById('advancedSearchToggle');
    panel.hidden = !panel.hidden;
    toggle?.setAttribute('aria-expanded', String(!panel.hidden));
    if (!panel.hidden) {
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.getElementById('searchPage').classList.add('active');
        search();
        document.getElementById('searchField').focus();
    }
}
function toggleDark() {
    isDark = !isDark;
    document.body.classList.toggle('dark', isDark);
    try { localStorage.setItem('isDark', JSON.stringify(isDark)); } catch(e) {}
    syncThemeButton();
}
function memoryTest(id = currentTopicId) {
    quizTopicId = Number(id) || currentTopicId;
    quizAnswerShown = false;
    const modal = document.getElementById('memoryQuiz');
    document.getElementById('quizTopicName').textContent = `الموضوع (${quizTopicId}): ${getTopicName(quizTopicId)}`;
    const answer = document.getElementById('quizAnswer');
    answer.innerHTML = topicTexts[quizTopicId] || '<p>لا يتوفر نص لهذا الموضوع.</p>';
    answer.hidden = true;
    document.getElementById('revealAnswerBtn').hidden = false;
    document.getElementById('quizGradeControls').hidden = true;
    modal.hidden = false;
    document.body.classList.add('quiz-open');
    document.getElementById('revealAnswerBtn').focus();
}
function revealMemoryAnswer() {
    if (!quizTopicId) return;
    quizAnswerShown = true;
    document.getElementById('quizAnswer').hidden = false;
    document.getElementById('revealAnswerBtn').hidden = true;
    document.getElementById('quizGradeControls').hidden = false;
}
function gradeMemoryTest(mastered) {
    const id = quizTopicId;
    const previous = reviewRecords[id] || {interval:0,repetitions:0};
    const now = Date.now();
    let intervalDays;
    if (mastered) {
        const repetitions = Number(previous.repetitions || 0) + 1;
        intervalDays = repetitions === 1 ? 1 : repetitions === 2 ? 3 : repetitions === 3 ? 7 : repetitions === 4 ? 14 : 30;
        reviewRecords[id] = {repetitions, interval:intervalDays, lastReviewed:new Date(now).toISOString(), nextReview:now + intervalDays*86400000, mastered:true};
        if (!savedTopics.includes(id)) { savedTopics.push(id); saveJSON('savedTopics', savedTopics); }
        showToast(`أحسنت! موعد المراجعة بعد ${intervalDays} ${intervalDays===1?'يوم':'أيام'}.`);
    } else {
        intervalDays = 0;
        reviewRecords[id] = {repetitions:0, interval:0, lastReviewed:new Date(now).toISOString(), nextReview:now + 10*60000, mastered:false};
        showToast('لا بأس، أعد المراجعة ثم اختبر نفسك من جديد.');
    }
    saveJSON('reviewRecords', reviewRecords);
    updateStats();
    closeMemoryTest();
    if (document.getElementById('memoryPage').classList.contains('active')) showMemory();
}
function closeMemoryTest() {
    const modal = document.getElementById('memoryQuiz');
    if (modal) modal.hidden = true;
    document.body.classList.remove('quiz-open');
    quizTopicId = 0;
}
function toggleBookmark() {
    const index = bookmarkedTopics.indexOf(currentTopicId);
    if (index >= 0) bookmarkedTopics.splice(index,1); else bookmarkedTopics.push(currentTopicId);
    saveJSON('bookmarkedTopics', bookmarkedTopics);
    updateBookmarkButton();
    showToast(index >= 0 ? 'تمت إزالة العلامة المرجعية' : 'تمت إضافة العلامة المرجعية');
}
function updateBookmarkButton() {
    const btn = document.getElementById('bookmarkBtn');
    if (!btn) return;
    const active = bookmarkedTopics.includes(currentTopicId);
    btn.classList.toggle('active', active);
    btn.textContent = active ? '🔖 تمت إضافة العلامة' : '🔖 إضافة علامة مرجعية';
}
function showBookmarks() {
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('bookmarksPage').classList.add('active');
    window.scrollTo(0,0);
    const container = document.getElementById('bookmarks');
    if (!bookmarkedTopics.length) {
        container.innerHTML = `<div class="empty"><div class="big">🔖</div><h3>لا توجد علامات مرجعية</h3><p>أضف علامة من داخل أي موضوع للعودة إليه بسرعة.</p></div>`;
        return;
    }
    container.innerHTML = [...new Set(bookmarkedTopics)].map(id => `<div class="result"><button type="button" onclick="openTopic(${Number(id)})"><small>علامة مرجعية · موضوع (${Number(id)})</small><strong>${escapeHTML(getTopicName(id))}</strong></button></div>`).join('');
}

function updateAudioFileNote(){
    const el=document.getElementById('audioFileNote');
    if(el) el.innerHTML='ملف هذا الباب: <code>audio/'+Number(currentTopicId)+'.mp3</code>';
}

function playAudio() {
    setupAudioForTopic(true);
}

function playRecordedTopicById(id) {
    if (!audioSources[id]) {
        showToast('لا يتوفر تسجيل صوتي لهذا الباب بعد');
        return;
    }
    openTopic(id);
    playAudio();
}

function setupAudioForTopic(autoPlay=false) {
    updateAudioFileNote();
    const box = document.getElementById('audioPlayer');
    audioElement = document.getElementById('audioElement');
    const src = audioSources[currentTopicId];
    repeatCurrent = 0;
    repeatingAudio = false;
    if (document.getElementById('repeatCount')) document.getElementById('repeatCount').value = String(repeatTarget);

    if(src) {
        box.hidden = false;
        if(audioElement.src !== new URL(src, location.href).href) audioElement.src = src;
        audioElement.playbackRate = Number(localStorage.getItem('audioSpeed')) || 1;
        const pos = Number(localStorage.getItem('audioPos_' + currentTopicId)) || 0;
        audioElement.currentTime = pos;
        if(autoPlay) audioElement.play().catch(()=>{});
        audioElement.onloadedmetadata = () => updateAudioProgress();
        audioElement.ontimeupdate = () => {
            localStorage.setItem('audioPos_' + currentTopicId, String(audioElement.currentTime));
            updateAudioProgress();
        };
        audioElement.onplay = () => {
            document.getElementById('audioPlayBtn').innerText = '⏸ إيقاف';
            document.getElementById('audioStopBtn').disabled = false;
        };
        audioElement.onpause = () => document.getElementById('audioPlayBtn').innerText = '▶ سماع الحديث';
        audioElement.onended = () => handleAudioEnded();
    } else {
        box.hidden = true;
        audioElement.removeAttribute('src');
        if (autoPlay) showToast('لا يتوفر تسجيل صوتي لهذا الباب بعد');
    }
}

function handleAudioEnded() {
    if (repeatTarget === 0 || repeatCurrent + 1 < repeatTarget) {
        repeatCurrent++;
        repeatingAudio = true;
        audioElement.currentTime = 0;
        audioElement.play().catch(()=>{});
        updateAudioProgress(`التكرار ${repeatCurrent + 1}${repeatTarget ? ' من ' + repeatTarget : ''}`);
        return;
    }
    localStorage.removeItem('audioPos_' + currentTopicId);
    document.getElementById('audioPlayBtn').innerText = '▶ سماع الحديث';
    repeatingAudio = false;
    if(document.getElementById('autoNext').checked && currentTopicId < 142) navigateTopic(1);
}

function toggleAudio() {
    if(audioSources[currentTopicId] && audioElement) {
        if(audioElement.paused) audioElement.play().catch(()=>{}); else audioElement.pause();
    } else {
        showToast('لا يتوفر تسجيل صوتي لهذا الباب بعد');
    }
}

function stopAudio() {
    if(audioElement && !audioElement.paused) {
        audioElement.pause();
        audioElement.currentTime = 0;
    }
    localStorage.removeItem('audioPos_' + currentTopicId);
    repeatCurrent = 0;
    repeatingAudio = false;
    const btn=document.getElementById('audioPlayBtn');
    if(btn) btn.innerText='▶ سماع الحديث';
    updateAudioProgress('تم إيقاف الاستماع');
}

function changeRepeatCount() {
    repeatTarget = Number(document.getElementById('repeatCount').value);
    localStorage.setItem('repeatCount', String(repeatTarget));
    repeatCurrent = 0;
    showToast(repeatTarget === 0 ? 'التكرار المستمر مفعل' : `سيُكرر الحديث ${repeatTarget} ${repeatTarget===1?'مرة':'مرات'}`);
}

function changeAudioSpeed() {
    const speed = Number(document.getElementById('audioSpeed').value);
    localStorage.setItem('audioSpeed', String(speed));
    if(audioElement) audioElement.playbackRate = speed;
}

function updateAudioProgress(message) {
    document.getElementById('audioProgressText').innerText = message || (audioElement && audioElement.duration ? `${formatTime(audioElement.currentTime)} / ${formatTime(audioElement.duration)}` : 'لم يبدأ الاستماع بعد');
}
function formatTime(sec) { if(!Number.isFinite(sec)) return '00:00'; sec=Math.max(0,Math.floor(sec)); return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0'); }

function copyTopic() {
    const title = document.getElementById('topicHead').innerText;
    const text = document.getElementById('topicText').innerText.trim();
    if (!navigator.clipboard?.writeText) { showToast('النسخ غير متاح في هذا السياق'); return; } navigator.clipboard.writeText(title + '\n\n' + text).then(()=>showToast('تم نسخ الحديث')).catch(()=>showToast('تعذر النسخ، حاول مرة أخرى'));
}

async function shareTopic() {
    const title = document.getElementById('topicHead').innerText;
    const text = document.getElementById('topicText').innerText.trim();
    if(navigator.share) { try { await navigator.share({title:title,text:text,url:location.href}); } catch(e){} }
    else { await navigator.clipboard?.writeText(title + '\n\n' + text); showToast('تم نسخ الحديث للمشاركة'); }
}

function changeFontSize(delta) {
    fontSize = Math.min(30, Math.max(17, fontSize + delta));
    localStorage.setItem('fontSize', String(fontSize));
    applyFontSize();
}
function applyFontSize() {
    const el=document.getElementById('topicText'); if(el) { el.style.fontSize=fontSize+'px'; document.getElementById('fontSizeLabel').innerText=fontSize+'px'; }
}
function toggleCategory(btn) {
    const list=btn.nextElementSibling, collapsed=list.classList.toggle('collapsed');
    btn.classList.toggle('collapsed', collapsed);
    const key='cat_' + btn.innerText.trim(); localStorage.setItem(key, collapsed ? '1':'0');
}
function updateContinueReading() {
    const box=document.getElementById('continueReading'); if(!box) return;
    if(lastReadTopic && lastReadTopic !== currentTopicId) { box.hidden=false; box.innerHTML=`📖 <strong>متابعة القراءة</strong><button onclick="openTopic(${lastReadTopic})">الموضوع رقم ${lastReadTopic} ←</button>`; } else box.hidden=true;
}
function showToast(message) {
    let t=document.getElementById('toast'); if(!t){ t=document.createElement('div'); t.id='toast'; t.className='toast'; document.body.appendChild(t); }
    t.textContent=message; t.classList.add('show'); clearTimeout(window.__toastTimer); window.__toastTimer=setTimeout(()=>t.classList.remove('show'),2200);
}


/* إيماءات اللمس ووضع القراءة */
function toggleReadingMode(force) {
    const enable = typeof force === 'boolean' ? force : !document.body.classList.contains('reading-mode');
    document.body.classList.toggle('reading-mode', enable);
    const exitButton = document.getElementById('exitReadingMode');
    const toggleButton = document.getElementById('readingModeToggle');
    if (exitButton) exitButton.hidden = !enable;
    if (toggleButton) {
        toggleButton.setAttribute('aria-pressed', String(enable));
        toggleButton.textContent = enable ? '✓ وضع القراءة مفعّل' : '☷ وضع القراءة';
    }
    if (enable) {
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.getElementById('topicPage')?.classList.add('active');
        window.scrollTo({top: 0, behavior: 'smooth'});
        showToast('وضع القراءة: اسحب يمينًا أو يسارًا للتنقل');
    } else {
        showToast('تم إنهاء وضع القراءة');
    }
}

(function setupTopicSwipeNavigation() {
    let startX = 0, startY = 0, tracking = false;
    const area = document.getElementById('topicPage');
    if (!area) return;
    area.addEventListener('touchstart', function(e) {
        if (!document.getElementById('topicPage').classList.contains('active') || e.touches.length !== 1) return;
        const target = e.target;
        if (target.closest('button, a, input, textarea, select, audio, video, .reading-tools, .audio-player, .actions, .section-nav-buttons')) return;
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
        tracking = true;
    }, {passive: true});
    area.addEventListener('touchend', function(e) {
        if (!tracking || !e.changedTouches.length) return;
        tracking = false;
        const dx = e.changedTouches[0].clientX - startX;
        const dy = e.changedTouches[0].clientY - startY;
        if (Math.abs(dx) < 65 || Math.abs(dx) < Math.abs(dy) * 1.25) return;
        // In RTL reading order, a left swipe advances and a right swipe goes back.
        navigateTopic(dx < 0 ? 1 : -1);
    }, {passive: true});
    area.addEventListener('touchcancel', () => { tracking = false; }, {passive: true});
})();

